package org.skhuconnect.admin.dashboard.service;
import org.skhuconnect.admin.dashboard.dto.AdminDashboardResponse; import org.skhuconnect.comment.repository.CommentRepository; import org.skhuconnect.petition.entity.PetitionStatus; import org.skhuconnect.petition.repository.PetitionRepository; import org.skhuconnect.report.entity.ReportStatus; import org.skhuconnect.report.repository.ReportRepository; import org.skhuconnect.user.repository.UserRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class AdminDashboardService { private final UserRepository users; private final PetitionRepository petitions; private final CommentRepository comments; private final ReportRepository reports; public AdminDashboardService(UserRepository users,PetitionRepository petitions,CommentRepository comments,ReportRepository reports){this.users=users;this.petitions=petitions;this.comments=comments;this.reports=reports;} @Transactional(readOnly=true) public AdminDashboardResponse get(){Map<PetitionStatus,Long> ps=new EnumMap<>(PetitionStatus.class); for(PetitionStatus s:PetitionStatus.values()) ps.put(s,petitions.countByStatusAndDeletedFalse(s)); Map<ReportStatus,Long> rs=new EnumMap<>(ReportStatus.class); for(ReportStatus s:ReportStatus.values()) rs.put(s,reports.countByStatus(s)); return new AdminDashboardResponse(users.count(),petitions.countByDeletedFalse(),ps,comments.countByDeletedFalse(),rs);}}
